=== REGISTERED ATTACKS (already covered) ===

A01 · out-of-band payment mid-ladder — double collection: §7's hard stop on out-of-band success
A02 · a link we sent is paid — the one settlement path with a join key that was not guessed
A03 · escalation without end — unbounded escalation once the retry budget is spent
A04 · every webhook delivered twice — event-plane idempotency, and closure-receipt uniqueness
A05 · same payment, fresh event id — semantic idempotency, where the event plane has nothing to match on
A06 · the check-then-act dedupe window, won — dedupe as an atomic insert rather than a read then a write
A07 · one human, two customer ids — the per-customer frequency cap, counted against the wrong unit
A08 · the contact window in the customer's timezone — RBI FPC 08:00-19:00, evaluated where the customer actually is
A09 · a message to a DND-listed customer — DNDGuard's jurisdiction over a message whose DLT category no one declared
A10 · queued at 17:05, due at 19:05 — the compliance check happening at execute time, on effective_at
A11 · four episodes, one identity — the frequency cap when identity resolution is not the problem
A12 · a mandate debit at the AFA threshold, and one paisa over — RBI's ₹15,000 e-mandate limit, both directions
A13 · consent withdrawn with work in flight — DPDP: purge the queue, close the episodes, refuse what arrives next
A14 · a future-dated event, delivered twice — clock-skew sanity bounds, and the closure receipt they write
A15 · a risk decline in the same instant as a due retry — a queued proposal outliving the diagnosis that built it
A16 · the card expires between attempt 2 and 3 — stale classification: the queued retry is never reclassified
A18 · a promise to pay releases a retry at midnight — taxonomy §6's quiet period on the retry half
A19 · a promise to pay defers the human handoff — taxonomy §7's immediate hard stop on RISK_BLOCK
A20 · two webhooks racing for the last attempt — the platform attempt ceiling under concurrent delivery
A22 · an amount past both merchant ceilings — blast radius: the daily spend cap and the unattended threshold
A23 · a mandate debit with no notice served — RBI e-mandate: the account is not touched inside the notice period
A24 · the failure arrives after the capture — event ordering: a terminal episode absorbs what comes late
A26 · a debit whose response is lost — a second debit after a lost response — invisible to every record but the rail's
A27 · out-of-band payment, with no settlement lookup wired — what A01's fix does *not* cover: the shipped default

=== THE GUARDS (source) ===

# ---- vasool/policy/guards/afa_threshold.py ----
"""Additional Factor of Authentication above the e-mandate threshold.

Escalates rather than blocks. The action is not forbidden — it needs a factor an
unattended system cannot supply. Refusing it outright would throw away a
recoverable payment over a step a human can complete in a minute.

**What the spec asks for, and why this does something else.** §6.2's behaviour
column says "route to AFA flow". There is no AFA_LINK in InterventionType, and
taxonomy.py's first rule is that adding a member is a taxonomy change that
belongs in docs/taxonomy.md before it belongs in code — precisely so that a
guard cannot invent an action at a call site. So this escalates to the human
queue, which is the honest available action, and the AFA row stays an open
question for the taxonomy rather than a quiet enum edit here.

**The limit depends on what the mandate pays for.** §8(a) of RBI's E-mandate
Framework, 2026 lets every recurring debit run without AFA "up to ₹15,000/-";
§8(b) raises that to ₹1,00,000 for insurance premiums, mutual-fund
subscriptions and credit-card bills. NPCI applies the higher tier by merchant
category code (OC-151A: "more than ₹1,00,000/-" needs the UPI PIN, "less than or
equal to" does not), so both limits are inclusive — exactly ₹15,000 passes and
one paisa more does not — and the category is read from the mandate record,
not held here as one constant.
"""
from __future__ import annotations

from vasool.mandate.citations import cite
from vasool.mandate.record import MandateCategory
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict

CITATION = cite(
    "RBI-EMF-2026 §8(a)", "RBI-EMF-2026 §8(b)", "NPCI-OC-151A ¶1", "NPCI-OC-151A Annexure A"
)

AFA_THRESHOLD_PAISE = 1_500_000
"""₹15,000 — §8(a), for every recurring debit not in a higher tier."""

AFA_HIGHER_TIER_PAISE = 10_000_000
"""₹1,00,000 — §8(b), for the three categories below."""

HIGHER_TIER: frozenset[MandateCategory] = frozenset(
    {
        MandateCategory.INSURANCE_PREMIUM,
        MandateCategory.MUTUAL_FUND,
        MandateCategory.CREDIT_CARD_BILL,
    }
)


def afa_limit_paise(category: MandateCategory) -> int:
    """The largest debit this category may take without additional authentication."""
    return AFA_HIGHER_TIER_PAISE if category in HIGHER_TIER else AFA_THRESHOLD_PAISE


class AFAThresholdGuard(Guard):
    name = "AFAThresholdGuard"
    statute = "RBI E-mandate Framework 2026 §8 — AFA above ₹15,000, or ₹1,00,000 by category"

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.facts.is_mandate and ctx.proposal.is_retry

    def check(self, ctx: GuardContext) -> Verdict:
        assert ctx.facts.mandate is not None  # is_mandate reads the record
        limit = afa_limit_paise(ctx.facts.mandate.category)
        if ctx.proposal.amount_paise > limit:
            return self.escalate(
                f"₹{ctx.proposal.amount_paise / 100:,.2f} exceeds the ₹"
                f"{limit / 100:,.0f} e-mandate limit for this mandate's category — this "
                "debit needs an authentication factor no unattended system can supply"
            )
        return self.allow()


# ---- vasool/policy/guards/autopay_peak_hours.py ----
"""UPI Autopay executions happen outside NPCI's peak hours.

NPCI's OC-215A/2025-26 lists "Autopay Mandate Execution" among the APIs its
members must moderate: "To be initiated in non-peak hours", where peak hours
are "10:00 hrs to 13:00 hrs and from 17:00 hrs to 21:30 hrs" and any other
time is non-peak. A recovery retry on a UPI Autopay mandate is an execution,
so it is held out of both windows. So is its pre-debit notice request: that is
NPCI's ValCust API (row 8), a call no customer initiated, and ¶3 has members
"restrict non-customer-initiated APIs" during peak hours — read here as
holding the request, the one restriction available to a single call. Card
mandates are not NPCI's, and nothing here touches them.

Defers rather than blocks: the rule is about when, never whether, exactly as
the contact window is.

**Two readings the circular leaves open, and the ones taken.** It names no
time zone; UPI's hours are India's, so the windows are read in IST. It does
not say whether 13:00 and 21:30 themselves are peak, so both ends are treated
as inside, and a held execution resumes a minute after — outside the window
on either reading.

**The jitter answers the same circular's other half.** Row 5(a) asks that
executions be "initiated at moderated TPS", and a guard that released every
held execution at 21:31:00 would build the burst the circular exists to
prevent. So each resumes somewhere in the quarter-hour after, at an offset
derived from the payment rather than drawn, for the reason
`contact_window.window_jitter` gives: the same seed must replay to the same
ledger.
"""
from __future__ import annotations

import hashlib
from datetime import datetime, time, timedelta

from vasool.diagnosis.proposal import ProposalRole
from vasool.diagnosis.rules import IST
from vasool.mandate.citations import cite
from vasool.mandate.record import MandateRail
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict

CITATION = cite("NPCI-OC-215A row 5", "NPCI-OC-215A row 8", "NPCI-OC-215A ¶3")

PEAK_HOURS_IST: tuple[tuple[time, time], ...] = ((time(10, 0), time(13, 0)), (time(17, 0), time(21, 30)))
"""Both ends inside. NPCI OC-215A/2025-26 ¶3."""

RESUME_AFTER_PEAK = timedelta(minutes=1)

EXECUTION_JITTER_MAX = timedelta(minutes=15)
"""# VERIFY: fifteen minutes is ours, matching the contact window's spread. The
circular asks for "moderated TPS" and names no number."""


def execution_jitter(entity_id: str) -> timedelta:
    """A stable per-payment offset into the quarter-hour after a peak."""
    digest = hashlib.sha256(entity_id.encode()).hexdigest()
    return timedelta(seconds=int(digest[:8], 16) % int(EXECUTION_JITTER_MAX.total_seconds()))


class AutopayPeakHoursGuard(Guard):
    name = "AutopayPeakHoursGuard"
    statute = "NPCI OC-215A/2025-26 — no Autopay execution or notice request at peak"

    def applies_to(self, ctx: GuardContext) -> bool:
        mandate = ctx.facts.mandate
        return (
            (ctx.proposal.is_retry or ctx.proposal.role is ProposalRole.PRE_DEBIT_NOTICE)
            and mandate is not None
            and mandate.rail is MandateRail.UPI_AUTOPAY
        )

    def check(self, ctx: GuardContext) -> Verdict:
        local = ctx.effective_at.astimezone(IST)
        for opens, closes in PEAK_HOURS_IST:
            if opens <= local.time() <= closes:
                resume = datetime.combine(local.date(), closes, tzinfo=IST) + RESUME_AFTER_PEAK
                return self.defer(
                    resume + execution_jitter(ctx.proposal.entity_id),
                    f"{local:%H:%M} IST is inside NPCI's {opens:%H:%M}-{closes:%H:%M} peak "
                    f"window, when a UPI Autopay {self._kind(ctx)} is not initiated",
                )
        return self.allow()

    @staticmethod
    def _kind(ctx: GuardContext) -> str:
        return "execution" if ctx.proposal.is_retry else "pre-debit notice request"


# ---- vasool/policy/guards/base.py ----
"""The Guard contract.

A guard is a pure function from a GuardContext to a Verdict. No I/O, no clock
beyond the two times on the context, no store — everything it needs was
snapshotted before the chain ran (vasool/policy/facts.py). That is what makes
the fifteen property-testable over a generated input space rather than over
three hand-written cases, and it is the claim the whole compliance argument
rests on.

`evaluate()` is final and does three things the individual guards must not be
trusted to remember:

  1. **Jurisdiction.** A guard with nothing to say returns NOT_APPLICABLE, not
     ALLOW. "The DLT template rule does not apply to a silent retry" and "the
     DLT template rule passed this message" are different claims and the report
     card must not render both as a tick.

  2. **Fail closed on missing facts.** A guard that declares a fact in
     `requires` never runs when that fact is None; the action is blocked
     instead. Without this, a bug in fact loading silently disables a compliance
     guard while every test still passes — the worst failure mode available to
     a system like this, because it is invisible.

  3. **Deferral progress.** A DEFER whose `defer_until` is not strictly after
     `effective_at` is a livelock, so it raises rather than returning. The
     Verdict model already refuses a DEFER with no time at all; this catches the
     subtler version where a guard computes one that has already passed.
"""
from __future__ import annotations

from abc import ABC, abstractmethod
from datetime import datetime
from typing import ClassVar, final

from vasool.policy.facts import GuardContext
from vasool.policy.verdict import Decision, Obligation, Verdict


class Guard(ABC):
    """One compliance rule. Pure."""

    name: ClassVar[str]
    statute: ClassVar[str | None] = None
    """The clause enforced, printed in the report card. None where the rule is
    self-imposed — a merchant's spend ceiling is not regulation and must not be
    dressed up as one in the single artefact a compliance reader will read
    closely."""

    requires: ClassVar[frozenset[str]] = frozenset()
    """PolicyFacts fields this guard cannot judge without.

    Name only facts whose None means *unknown*. `promise_to_pay` is None when
    the customer made no promise — known, and absent — so a guard that declared
    it would refuse every action for want of a promise nobody made.

    A guard reading a fact it did not declare is a bug this cannot catch, so
    declare honestly. tests/test_guard_properties.py checks that every declared
    name is a real field, which catches the typo but not the omission.
    """

    def applies_to(self, ctx: GuardContext) -> bool:
        """Whether this guard has jurisdiction over this proposal."""
        return True

    @abstractmethod
    def check(self, ctx: GuardContext) -> Verdict:
        """The rule. Called only when applies_to and every required fact is
        present."""

    @final
    def evaluate(self, ctx: GuardContext) -> Verdict:
        if not self.applies_to(ctx):
            return self.not_applicable()

        missing = sorted(name for name in self.requires if getattr(ctx.facts, name) is None)
        if missing:
            return self.block(
                f"cannot judge: {', '.join(missing)} unavailable. A fact we have "
                "not established is not the same as one we have established to "
                "be harmless, so this fails closed."
            )

        verdict = self.check(ctx)
        if verdict.guard != self.name:
            raise ValueError(f"{type(self).__name__} returned a verdict for {verdict.guard!r}")
        if verdict.defer_until is not None and verdict.defer_until <= ctx.effective_at:
            raise ValueError(
                f"{self.name} deferred to {verdict.defer_until}, which is not after "
                f"{ctx.effective_at} — a deferral that does not advance is a livelock"
            )
        return verdict

    # -- verdict constructors, so that `guard` and `statute` are never
    # -- transcribed by hand at a call site
    def allow(self, reason: str | None = None) -> Verdict:
        """Permitted. `reason` is optional and exists for the guards whose
        ALLOW is surprising to read.

        `RiskBlockGuard` is the case that motivated it: on a risk decline the
        taxonomy has already chosen `HUMAN_QUEUE`, so the guard has nothing left
        to refuse and allows — which, printed in a chain next to the words
        "Card network norms", reads as the guard failing. It is the opposite.
        A receipt that cannot be read correctly is a worse audit trail than a
        terse one.
        """
        return Verdict(
            guard=self.name, decision=Decision.ALLOW, reason=reason, statute=self.statute
        )

    def not_applicable(self) -> Verdict:
        return Verdict(guard=self.name, decision=Decision.NOT_APPLICABLE)

    def block(self, reason: str) -> Verdict:
        return Verdict(
            guard=self.name, decision=Decision.BLOCK, reason=reason, statute=self.statute
        )

    def escalate(self, reason: str) -> Verdict:
        return Verdict(
            guard=self.name, decision=Decision.ESCALATE, reason=reason, statute=self.statute
        )

    def defer(
        self, until: datetime, reason: str, obligations: tuple[Obligation, ...] = ()
    ) -> Verdict:
        return Verdict(
            guard=self.name,
            decision=Decision.DEFER,
            reason=reason,
            statute=self.statute,
            defer_until=until,
            obligations=obligations,
        )


# ---- vasool/policy/guards/consent.py ----
"""DPDP: valid consent, matching purpose, not withdrawn.

Two rules, not one, because consent does not cover everything equally.

**Contact needs consent for this purpose.** Purpose limitation is the substance
of the regime: a record listing "marketing" does not authorise a dunning
message, and treating any consent as blanket consent would be the most ordinary
way to get this wrong.

**A silent retry does not.** Re-presenting an instrument the customer already
authorised is not a communication — the lawful basis is the mandate or the
contract, not permission to be messaged. Blocking a retry for want of *messaging*
consent would refuse the one intervention in the taxonomy that disturbs nobody.

**Withdrawal stops everything.** Not just contact. The design spec's stopping
rule is "immediate, purge queue", and adversary attack A12 is specifically about
a system that mutes the messages and quietly keeps charging. A withdrawal is a
signal about the relationship, not about a channel.

Purging is the state machine's job — a guard is pure and cannot empty a queue.
This is the backstop that catches anything already in flight.
"""
from __future__ import annotations

from vasool.policy.facts import CONSENT_PURPOSE_RECOVERY, GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict


class ConsentGuard(Guard):
    name = "ConsentGuard"
    statute = "DPDP Act 2023 s.6 + DPDP Rules 2025"
    # VERIFY: the DPDP Rules 2025 commencement timeline is on the day-one
    # checklist (design spec §15) and was not confirmed. The section reference
    # for consent is from the Act as passed.

    requires = frozenset({"consent"})
    """None means no record, which is unknown rather than absent. Fail closed:
    a customer we hold no consent record for is not a customer who consented."""

    def check(self, ctx: GuardContext) -> Verdict:
        consent = ctx.facts.consent
        assert consent is not None  # guaranteed by `requires`

        if consent.is_withdrawn(ctx.effective_at):
            return self.block(
                "consent withdrawn — a hard stop on the whole episode, not a "
                "mute on the messaging half"
            )
        if ctx.proposal.is_contact and not consent.covers(
            CONSENT_PURPOSE_RECOVERY, ctx.effective_at
        ):
            return self.block(
                f"no live consent for {CONSENT_PURPOSE_RECOVERY!r} — consent held "
                f"for {sorted(consent.purposes)} does not extend to it"
            )
        return self.allow()


# ---- vasool/policy/guards/contact_window.py ----
"""08:00-19:00 IST. The guard the whole pitch is built on.

A naive implementation blocks a 7:30pm nudge and loses the recovery. This one
defers it to just after eight: same compliance outcome, money still recovered.

Three things are worth reading closely.

**It reads `effective_at`, never `now`.** Adversary attack A04 is an action
queued at 18:58 that executes at 19:02; checked against the decision time it
passes, and the message lands outside the window. The design spec's own property
test in §6.3 asserts against `ctx.now` and so encodes the bug it is meant to
catch. The state machine closes the same gap from the other side by gating
immediately before execution rather than at propose time.

**It owns contact timing outright.** vasool/diagnosis/rules.py used to hold
outbound contact out of 00:00-06:00 as well, which meant two planes moving the
same action for the same reason — and 08:00-19:00 is a strict superset of that
window, so the earlier move never changed an outcome. taxonomy.md §6 already
argued these were two rules with different force: the retry half is an efficacy
hedge about issuer batch maintenance and stayed in the classifier, the contact
half is a permission rule about disturbing a human and belongs here. One rule,
one owner, and the compliance save now appears in the receipt instead of being
silently pre-applied upstream.

**The jitter is real, not decoration.** It is where the pitch's "8:02am" comes
from. Without it a merchant's entire overnight backlog fires at 08:00:00.000 —
a self-inflicted thundering herd, and a burst of simultaneous messages that
reads to a recipient exactly like the automated dunning the rule is trying to
prevent. It is derived from the customer id rather than drawn at random, because
architectural invariant 5 requires the same seed to produce a byte-identical ledger.
"""
from __future__ import annotations

import hashlib
from datetime import datetime, timedelta

from vasool.diagnosis.rules import IST
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict

CONTACT_WINDOW_OPEN_HOUR_IST = 8
CONTACT_WINDOW_CLOSE_HOUR_IST = 19
"""RBI Fair Practices Code: recovery contact between 08:00 and 19:00 only.
Half-open — 19:00 itself is outside."""

CONTACT_JITTER_MAX = timedelta(minutes=15)
"""Spread over the first quarter-hour of the window.

# VERIFY: fifteen minutes is ours. It wants sizing against real backlog volume —
# large enough to flatten the burst, small enough that nobody waits meaningfully
# longer than the window's opening.
"""


def window_jitter(customer_id: str) -> timedelta:
    """A stable per-customer offset into the opening of the window.

    Deterministic and process-independent: sha256 rather than hash(), which is
    salted per process and would replay differently tomorrow.
    """
    digest = hashlib.sha256(customer_id.encode()).hexdigest()
    return timedelta(seconds=int(digest[:8], 16) % int(CONTACT_JITTER_MAX.total_seconds()))


class ContactWindowGuard(Guard):
    name = "ContactWindowGuard"
    statute = "RBI Fair Practices Code ¶55"
    # VERIFY: the paragraph number is from the design spec's research and was
    # not confirmed against the current Code (design spec §15 lists it as a
    # day-one check). The 08:00-19:00 window is the well-established part; the
    # citation is the part to check before anyone prints it.

    # Fixed 2026-08-30. This guard evaluated the window in IST unconditionally,
    # so a customer elsewhere was protected by the merchant's clock rather than
    # their own -- adversary attack A08 lands a message at 22:30 customer-local
    # by deferring an 03:00 IST failure to the opening of *our* window. It now
    # reads `facts.customer_zone` and falls back to IST when that is unknown,
    # which is every customer the simulator builds, so no evaluated number
    # moves. taxonomy.md §9.3 carries the before/after.

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.proposal.is_contact

    def check(self, ctx: GuardContext) -> Verdict:
        # The customer's zone where we have one, the merchant's where we do
        # not. The deferral target is computed in the same zone it was judged
        # in -- deferring to 08:00 of the *wrong* clock is the original defect,
        # not a smaller version of it.
        zone = ctx.facts.customer_zone or IST
        label = "IST" if zone is IST else f"{zone}"
        local = ctx.effective_at.astimezone(zone)
        if CONTACT_WINDOW_OPEN_HOUR_IST <= local.hour < CONTACT_WINDOW_CLOSE_HOUR_IST:
            return self.allow()

        opens = local.replace(
            hour=CONTACT_WINDOW_OPEN_HOUR_IST, minute=0, second=0, microsecond=0
        )
        if local.hour >= CONTACT_WINDOW_CLOSE_HOUR_IST:
            opens += timedelta(days=1)

        return self.defer(
            opens + window_jitter(ctx.proposal.customer_id),
            f"{local:%H:%M} {label} is outside the {CONTACT_WINDOW_OPEN_HOUR_IST:02d}:00-"
            f"{CONTACT_WINDOW_CLOSE_HOUR_IST:02d}:00 contact window",
        )


# ---- vasool/policy/guards/dlt_template.py ----
"""TRAI: commercial messages go out on a registered template, or not at all.

Blocks rather than defers. A registration could in principle be added — but not
on any schedule anyone can name, and the defer-vs-block rule in this package is
that a deferral requires a concrete instant at which the condition expires. "A
human might register this template eventually" is not one.

The template a proposal carries is what *we* would send. This checks it against
what the *merchant* has registered. A template we can emit and the merchant has
not registered is exactly the case this exists to catch, so the two sets are
deliberately kept apart rather than derived from each other.
"""
from __future__ import annotations

from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict


class DLTTemplateGuard(Guard):
    name = "DLTTemplateGuard"
    statute = "TRAI TCCCPR — DLT template registration (Feb 2025 amendment)"

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.proposal.is_contact

    def check(self, ctx: GuardContext) -> Verdict:
        template = ctx.proposal.template_id
        if template is None:
            return self.block("outbound message carries no DLT template id")
        if template not in ctx.facts.registered_templates:
            return self.block(f"template {template!r} is not registered to this merchant")
        return self.allow()


# ---- vasool/policy/guards/dnd.py ----
"""TRAI's Do Not Disturb registry.

Scope is the whole question here, and it is not settled. The registry governs
*promotional* traffic; transactional and service messages are treated
differently. Under TCCCPR a message's category is the category its template is
registered under on DLT — the merchant's registration, not the message's
content — so whether a payment-recovery message is transactional, service or
promotional is a fact about the merchant, and this system cannot know it.

**So an undeclared category is judged, not waved through.** The effective
category is the merchant's declaration for the proposal's template
(`PolicyFacts.template_categories`) when there is one, and the proposal's own
otherwise — which the diagnosis now always builds as UNKNOWN. This guard has
jurisdiction over PROMOTIONAL and over UNKNOWN. A merchant that declares a
template TRANSACTIONAL or SERVICE takes that message out of its jurisdiction,
and takes on the obligation of the declaration being true.

Until 2026-09-15 every contact was built as TRANSACTIONAL, so this guard
returned NOT_APPLICABLE for everything the system ever sent, and adversary
attack A09 — a message to a DND-listed customer — was registered as a failure
(docs/EVALUATION.md §10, 2026-09-15).

**Unknown blocks.** A registry that cannot answer leaves `dnd_listed` None, and
the guard base fails closed on a required fact it does not have: "unknown,
therefore blocked", never "unknown, therefore fine". `vasool/policy/
dnd_registry.py` is the port a real scrub will arrive through, and its null
adapter answers exactly that.

**Staleness blocks too.** In production `dnd_listed` is a network call. A scrub
from last month does not answer a registration made last week, and — more to
the point — a call that failed must not be indistinguishable from a clean
result.
"""
from __future__ import annotations

from datetime import timedelta

from vasool.diagnosis.proposal import MessageCategory
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict

DND_FACT_TTL = timedelta(days=7)
"""How long a registry scrub is trusted.

# VERIFY: ours, not TRAI's. The regime's actual scrub-frequency obligation sits
# with the registered sender and was not confirmed (design spec §15). Seven days
# is short enough that a fresh registration is caught within a week and long
# enough not to make every message a network round-trip.
"""

JURISDICTION = frozenset({MessageCategory.PROMOTIONAL, MessageCategory.UNKNOWN})
"""The categories the registry is held to govern. UNKNOWN is here because an
unknown category is not a transactional one."""


def effective_category(ctx: GuardContext) -> MessageCategory | None:
    """The merchant's declaration for this template, else the proposal's own."""
    declared = ctx.facts.declared_category(ctx.proposal.template_id)
    return declared if declared is not None else ctx.proposal.message_category


class DNDGuard(Guard):
    name = "DNDGuard"
    statute = "TRAI TCCCPR 2018 (as amended Feb 2025)"
    requires = frozenset({"dnd_listed", "dnd_checked_at"})

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.proposal.is_contact and effective_category(ctx) in JURISDICTION

    def check(self, ctx: GuardContext) -> Verdict:
        checked_at = ctx.facts.dnd_checked_at
        assert checked_at is not None  # guaranteed by `requires`

        age = ctx.effective_at - checked_at
        if age > DND_FACT_TTL:
            return self.block(
                f"DND scrub is {age.days}d old, past the {DND_FACT_TTL.days}d TTL — "
                "a stale scrub and a failed one look identical, so neither is trusted"
            )
        if ctx.facts.dnd_listed:
            return self.block(
                f"customer is on the DND registry, and this message's category is "
                f"{effective_category(ctx).value}"
            )
        return self.allow()


# ---- vasool/policy/guards/frequency_cap.py ----
"""Anti-harassment. Two caps, and they resolve differently.

**Three contacts per customer per seven days: DEFER.** This condition expires.
The oldest contact ages out of the window at a computable instant, so there is a
real time to name and the recovery survives.

**Two contacts per recovery episode: BLOCK.** This condition does not expire. An
episode does not get shorter by waiting, so a deferral here would be a deferral
forever — the exact pathology the defer-vs-block rule exists to prevent.

Both caps appear in both stopping-rule tables (design spec §5, taxonomy §7) and
in none of the spec's thirteen guards. They live together here because they
count the same thing over different windows, and because a reader looking for
"how often do we message someone" should find one file.

The episode cap is two because §4's insufficient_fund row spends exactly two —
one soft nudge, then a re-attempt link once three timed retries have failed. The
row was built to sit at the cap rather than to breach it.
"""
from __future__ import annotations

from datetime import timedelta

from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict

FREQUENCY_CAP_WINDOW = timedelta(days=7)
FREQUENCY_CAP_COUNT = 3
"""Design spec §5 and taxonomy §7: at most three outbound contacts per customer
per seven days. Self-imposed, in the spirit of the Fair Practices Code rather
than in satisfaction of a numbered clause."""

EPISODE_CONTACT_CAP = 2
"""At most two contacts in one recovery episode."""


class FrequencyCapGuard(Guard):
    name = "FrequencyCapGuard"
    statute = "RBI Fair Practices Code (anti-harassment)"

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.proposal.is_contact

    def check(self, ctx: GuardContext) -> Verdict:
        # Checked first: one verdict per guard, and the cap that can never
        # expire has to win, or we would schedule an action that is already
        # dead and call it a compliance save.
        if ctx.facts.episode_contacts >= EPISODE_CONTACT_CAP:
            return self.block(
                f"{ctx.facts.episode_contacts} contacts already sent in this "
                f"episode (cap {EPISODE_CONTACT_CAP}) — one is a reminder, two "
                "is pressure, and an episode does not get shorter by waiting"
            )

        window_opens = ctx.effective_at - FREQUENCY_CAP_WINDOW
        in_window = sorted(
            t for t in ctx.facts.contact_history if window_opens < t <= ctx.effective_at
        )
        if len(in_window) < FREQUENCY_CAP_COUNT:
            return self.allow()

        # The oldest contact leaves the window exactly one window-length after
        # it was sent, and that is the first instant a further contact is
        # permitted. Strictly after effective_at by construction, since every
        # member of in_window is strictly after window_opens.
        return self.defer(
            in_window[0] + FREQUENCY_CAP_WINDOW,
            f"{len(in_window)} contacts in the last {FREQUENCY_CAP_WINDOW.days}d "
            f"(cap {FREQUENCY_CAP_COUNT})",
        )


# ---- vasool/policy/guards/human_approval.py ----
"""Above a merchant's threshold, a person decides. Last in the chain.

Self-imposed, and the last line of defence rather than a compliance rule: for a
large enough amount, the right answer is that an automated system does not act
unattended however clean the other fourteen verdicts are.

Skips anything already bound for a human. Escalating an escalation would queue
the same item twice and make the queue depth a lie. Skips a status check too:
it reads the rail and moves nothing, and on a large debit whose outcome is in
doubt, finding out whether the money moved is the most useful thing to do
unattended.
"""
from __future__ import annotations

from vasool.diagnosis.taxonomy import InterventionType
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict


class HumanApprovalGuard(Guard):
    name = "HumanApprovalGuard"
    statute = None

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.proposal.intervention not in (
            InterventionType.HUMAN_QUEUE,
            InterventionType.STATUS_CHECK,
        )

    def check(self, ctx: GuardContext) -> Verdict:
        threshold = ctx.facts.merchant.human_approval_threshold_paise
        if ctx.proposal.amount_paise > threshold:
            return self.escalate(
                f"₹{ctx.proposal.amount_paise / 100:,.2f} is over this merchant's "
                f"₹{threshold / 100:,.2f} unattended-action threshold"
            )
        return self.allow()


# ---- vasool/policy/guards/idempotency.py ----
"""One execution per action. Not a compliance rule — a correctness one.

Razorpay delivers every webhook at least twice with an identical event id
(docs/VERIFIED.md), so this is normal operation rather than a defensive
nicety. The event plane dedupes on `x-razorpay-event-id`; this is the backstop
for the delivery that gets past it, and for adversary attack A02, where the same
payment arrives under a *fresh* event id and the event-plane check has nothing
to match on.

The design spec keys this on `(event_id, intervention)`, which is wrong twice:

  - It collides across attempts. `gateway_technical_error` earns three silent
    retries for one event; under that key, retry 2 is a duplicate of retry 1 and
    a three-retry row silently becomes a one-retry row.
  - It misses A02 entirely, which is the harder half of the attack pair and the
    one the spec itself flags as "semantic idempotency (harder)".

Proposal.idempotency_key keys on the payment instead — see there.
"""
from __future__ import annotations

from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict


class IdempotencyGuard(Guard):
    name = "IdempotencyGuard"
    statute = None
    """Deliberately none. Deduplication is engineering, and listing it beside
    the RBI and DPDP citations would pad the compliance table with a row that
    enforces no clause."""

    def check(self, ctx: GuardContext) -> Verdict:
        key = ctx.proposal.idempotency_key
        if key in ctx.facts.executed_keys:
            return self.block(f"already executed: {key}")
        return self.allow()


# ---- vasool/policy/guards/mandate_state.py ----
"""A debit needs a live mandate.

The mandate is the only authority a recurring debit has. §4(b) of RBI's
E-mandate Framework, 2026 gives the customer a facility to withdraw it "at any
point of time", and a recovery retry is built days before it executes — the
salary ladder waits for payday — so the authority it was built on can be gone
by the time it runs. This guard reads the mandate at the moment the debit would
reach the rail, through `MandateRecord.state_at`, which also applies the two
transitions nobody has to apply: a validity period ending and a pause lapsing.

**It blocks, and does not defer — a pause included.** A paused mandate will
work again when the pause ends, so deferring to that moment is available. It is
not taken: the customer paused the mandate to stop being debited, and a retry
held until the pause lifts is that debit, collected anyway. The rail would
decline it now in any case (NPCI code VT, "MANDATE IS PAUSED"). Whether to ask
the customer for the money another way is a contact, and the contact guards
rule on that separately.
"""
from __future__ import annotations

from vasool.mandate.citations import cite
from vasool.mandate.states import MandateState
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict

CITATION = cite(
    "RBI-EMF-2026 §4(a)",
    "RBI-EMF-2026 §4(b)",
    "NPCI-UPI-CODES-2.9 §3.1 VA",
    "NPCI-UPI-CODES-2.9 §3.1 VT",
    "NPCI-UPI-CODES-2.9 §3.1 VU",
)
"""The clauses behind every refusal below, quoted in vasool/mandate/citations.py."""

_REFUSALS: dict[MandateState, str] = {
    MandateState.CREATED: (
        "the mandate is not registered: registration completes only on the customer's "
        "additional factor of authentication"
    ),
    MandateState.PENDING_AUTH: (
        "the mandate is awaiting the customer's authentication and is not yet registered"
    ),
    MandateState.PAUSED: (
        "the customer has paused this mandate; a debit now is one they asked not to "
        "receive (NPCI VT, MANDATE IS PAUSED)"
    ),
    MandateState.REVOKED: (
        "the mandate has been revoked, and a withdrawn authority does not come back "
        "(NPCI VA, MANDATE HAS BEEN REVOKED)"
    ),
    MandateState.EXPIRED: (
        "the mandate's validity period has ended (NPCI VU, MANDATE HAS EXPIRED)"
    ),
}


class MandateStateGuard(Guard):
    name = "MandateStateGuard"
    statute = "RBI E-mandate Framework 2026 §4 — debit only under a live mandate"

    def applies_to(self, ctx: GuardContext) -> bool:
        return (ctx.facts.is_mandate or ctx.facts.mandate_unknown) and ctx.proposal.is_retry

    def check(self, ctx: GuardContext) -> Verdict:
        if ctx.facts.mandate is None:
            # Jurisdiction came from not knowing. A debit whose authority cannot
            # be established does not run — the refusal is the same shape as
            # the fail-closed block in Guard.evaluate for a fact we lack.
            return self.block(
                "cannot tell whether this payment is presented under a mandate. A "
                "debit whose authority has not been established is not the same as "
                "one established to need none, so this fails closed."
            )
        state = ctx.facts.mandate.state_at(ctx.effective_at)
        if state is MandateState.ACTIVE:
            return self.allow()
        return self.block(_REFUSALS[state])


# ---- vasool/policy/guards/pre_debit_notice.py ----
"""RBI e-mandate: the customer is notified before a recurring debit.

This guard is the clearest case of the rule that a guard describes and never
performs. It cannot request a notice — it is a pure function — so when one is
owed it defers the debit and returns an inert Obligation saying so. The state
machine turns that into a Proposal, and *that proposal goes through the guard
chain like any other*: an obligation that short-circuited into an executor
would be a hole straight through the policy plane, and describing it as a
proposal and re-gating it closes the hole structurally.

**The notice is the issuer's; the merchant only asks for it.** §6(a) of RBI's
E-mandate Framework, 2026: "An issuer shall send a pre-transaction
notification to the customer, at least 24 hours prior to the actual charge /
debit." For UPI the merchant's part is a request through the rail — the
payee's PSP calls NPCI's pre-debit notification API, ReqValCust, 24 hours ahead
(OC-149's annexure, code NU) — and the PSP and the issuing bank then notify the
customer (OC-151A ¶4). So the proposal the obligation becomes is not a
message: it has no channel and no template, the executor hands it to
`vasool/actions/notice.py` rather than to comms, and the rules written for a
merchant's messages — the contact window, DND, DLT, the contact caps — have no
jurisdiction over it. Until docs/EVALUATION.md §10, 2026-09-15, it was built as
the merchant's SMS and gated through all four, which held many debits for a
notice those rules refused.

# VERIFY: this whole path is stub-only. Subscriptions are unavailable
# pre-activation on this account (docs/VERIFIED.md), so no mandate debit has
# ever been observed, and the mandate record is one a simulator builds rather
# than one any payload carries.
"""
from __future__ import annotations

from datetime import timedelta

from vasool.mandate.citations import cite
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Obligation, ObligationKind, Verdict

CITATION = cite("RBI-EMF-2026 §6(a)")
"""The rule this guard enforces: the 24 hours."""

WHO_SENDS_IT = cite("RBI-EMF-2026 §6(a)", "NPCI-OC-149A Annexure NU", "NPCI-OC-151A ¶4")
"""The evidence that the issuer notifies, through the rail — and so why the
notice is not a contact (docs/EVALUATION.md §10, 2026-09-15)."""

PRE_DEBIT_NOTICE_LEAD = timedelta(hours=24)
"""How far ahead of a mandate debit the customer must be notified: "at least 24
hours prior to the actual charge / debit" (RBI E-mandate Framework, 2026, §6(a)).
Inclusive — a notice exactly 24 hours old has matured."""


class PreDebitNoticeGuard(Guard):
    name = "PreDebitNoticeGuard"
    statute = "RBI E-mandate Framework 2026 §6(a) — pre-debit notification, 24 hours"

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.facts.is_mandate and ctx.proposal.is_retry

    def check(self, ctx: GuardContext) -> Verdict:
        sent_at = ctx.facts.pre_debit_notice_sent_at
        if sent_at is None:
            return self.defer(
                ctx.effective_at + PRE_DEBIT_NOTICE_LEAD,
                "no pre-debit notice has been served for this debit",
                obligations=(
                    Obligation(
                        kind=ObligationKind.SEND_PRE_DEBIT_NOTICE,
                        not_before=ctx.now,
                        reason=(
                            "the debit is held until the customer has had "
                            f"{PRE_DEBIT_NOTICE_LEAD} of notice"
                        ),
                    ),
                ),
            )

        deadline = sent_at + PRE_DEBIT_NOTICE_LEAD
        if ctx.effective_at >= deadline:
            return self.allow()
        return self.defer(
            deadline,
            f"notice served {sent_at.isoformat()}; the customer is owed the full "
            f"{PRE_DEBIT_NOTICE_LEAD} before the account is touched",
        )


# ---- vasool/policy/guards/promise_to_pay.py ----
"""No chasing during an active promise to pay.

The design spec calls this `QuietPeriodGuard`. Renamed, because
vasool/diagnosis/rules.py already uses "quiet period" for the 00:00-06:00 IST
exclusion, and two adjacent modules using one name for two unrelated rules is a
bug waiting to be written by whoever reads them next.

**It holds retries as well as contact.** The two source documents disagree:
design spec §6.2's guard table says "no contact during an active
promise-to-pay", while its own stopping-rule table says "hard stop ... until
promised date +1d". The broader reading is right. Debiting on the 3rd someone
who has promised to pay by the 5th is precisely the bad faith the Fair Practices
Code is about, and the fact that the debit is silent does not make it courteous.

**It defers, never blocks.** A promise is the strongest signal of intent
anywhere in the system. Killing a recovery because the customer said they would
pay would be the most perverse outcome the policy plane could produce.
"""
from __future__ import annotations

from datetime import datetime, timedelta

from vasool.diagnosis.rules import IST
from vasool.diagnosis.taxonomy import InterventionType
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict

PROMISE_GRACE = timedelta(days=1)
"""Design spec §5: the hold runs "until promised date +1d".

Read as: we do not chase on the promised day, and the hold lifts at the start of
the following day. The grace is what stops us chasing at one minute past
midnight over a payment that settles during the promised day.

# VERIFY: whether the grace should instead run a full day *past* the promised
# date is a product judgment nobody has made. The stricter reading costs one day
# of latency on a customer who has already told us they intend to pay, which is
# the cheap direction to be wrong in.
"""


class PromiseToPayGuard(Guard):
    name = "PromiseToPayGuard"
    statute = "RBI Fair Practices Code (fair dealing)"
    # VERIFY: the Fair Practices Code's applicability to a payment-gateway
    # recovery flow is by analogy — it governs regulated lenders' recovery
    # conduct. We hold ourselves to it because the conduct is the same conduct,
    # not because we have established that it binds a merchant's agent.

    def applies_to(self, ctx: GuardContext) -> bool:
        """A human handoff is not automated chasing, and neither is a status check.

        A risk decline must reach an operator immediately.  Holding
        HUMAN_QUEUE until a customer's promise expires delays the very review
        that makes the risk path safe (A19). A status check asks the rail
        whether a debit already happened and reaches no one; holding it for a
        promise would leave a possible double debit unexamined for days.
        """
        return ctx.proposal.intervention not in (
            InterventionType.HUMAN_QUEUE,
            InterventionType.STATUS_CHECK,
        )

    def check(self, ctx: GuardContext) -> Verdict:
        promise = ctx.facts.promise_to_pay
        if promise is None:
            return self.allow()

        lifts_on = promise + PROMISE_GRACE
        lifts_at = datetime(lifts_on.year, lifts_on.month, lifts_on.day, tzinfo=IST)
        if ctx.effective_at >= lifts_at:
            return self.allow()

        return self.defer(
            lifts_at,
            f"customer promised to pay by {promise.isoformat()}; chasing inside "
            "a promise is bad faith whether or not the customer notices",
        )


# ---- vasool/policy/guards/retry_cap.py ----
"""How many times the instrument may be re-presented, in total.

This is the *platform's* ceiling, and it is not the same number as the
taxonomy's per-row budget. §4 gives `card_expired` zero retries and
`gateway_technical_error` three; those are arguments about whether a retry could
possibly work, they are applied in classify(), and they are tighter than this in
every row. This guard is the outer bound: whatever proposed the action — the
rules, an LLM, a hand-built object — nothing exceeds what Razorpay itself will
tolerate before it halts the subscription.

Counted across the episode, not the event. Razorpay halts on *consecutive
failures* against a subscription, so a counter that reset per webhook would
measure the wrong thing entirely.

The one-time cap is stricter than the mandate cap on purpose. Nothing halts a
one-time payment on our behalf, so the restraint has to be ours.

**A UPI Autopay mandate has a rail's cap, and it is tighter.** NPCI permits
"Maximum of 1 attempt and 3 retries per mandate (per sequence number)"
(OC-215A/2025-26, row 5), so after the failure that opened an episode three
re-presentations remain, not four. That is a rule, not platform behaviour, and
it is the one cap here with a citation.
"""
from __future__ import annotations

from vasool.mandate.citations import cite
from vasool.mandate.record import MandateRail
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict

UPI_AUTOPAY_RETRY_CAP = 3
"""NPCI OC-215A/2025-26, row 5: one attempt, then three retries, per sequence
number. The attempt is the failure that opened the episode, so `attempts_used`
— re-presentations executed — may reach three."""

UPI_AUTOPAY_CITATION = cite("NPCI-OC-215A row 5")

MANDATE_ATTEMPT_CAP = 4
"""Razorpay halts a subscription after four consecutive failures.

# VERIFY: documented, never observed. Subscriptions are unavailable
# pre-activation on this account (docs/VERIFIED.md), so the halt rule could not
# be exercised and this number is taken from documentation — the one number in
# the policy plane that is.
"""

ONETIME_ATTEMPT_CAP = 3
"""Self-imposed. Nothing halts a one-time payment for us, so the ceiling is
ours to set, and it is set below the mandate cap rather than at it."""


class RetryCapGuard(Guard):
    name = "RetryCapGuard"
    statute = None
    """Razorpay's halt behaviour is platform behaviour, not regulation. The UPI
    Autopay cap is NPCI's rule, and its refusal names the circular in its own
    reason rather than lending the whole guard a statute the other two caps do
    not have."""

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.proposal.is_retry

    def check(self, ctx: GuardContext) -> Verdict:
        mandate = ctx.facts.mandate
        used = ctx.facts.attempts_used
        if mandate is not None and mandate.rail is MandateRail.UPI_AUTOPAY:
            if used >= UPI_AUTOPAY_RETRY_CAP:
                return self.block(
                    f"{used} of {UPI_AUTOPAY_RETRY_CAP} retries already spent on this UPI "
                    "Autopay mandate — NPCI permits one attempt and three retries per "
                    "sequence number (OC-215A/2025-26)"
                )
            return self.allow()

        cap = MANDATE_ATTEMPT_CAP if mandate is not None else ONETIME_ATTEMPT_CAP
        if used >= cap:
            kind = "mandate" if mandate is not None else "one-time payment"
            return self.block(
                f"{used} of {cap} attempts already spent on this {kind} — "
                "further re-presentation buys nothing and, on a mandate, is what "
                "triggers the halt"
            )
        return self.allow()


# ---- vasool/policy/guards/risk_block.py ----
"""A fraud engine declined this. Nothing automated, ever.

docs/taxonomy.md §2 argues this on four independent grounds — card-network rules
on retrying declined authorisations, the merchant's decline ratio, handing a
retry loop to a fraudster if it really was fraud, and the fact that an
unexpected payment link to a possibly-compromised customer is structurally
indistinguishable from phishing if it wasn't.

The taxonomy already routes both RISK_BLOCK rows to a human queue, so on the
rules path this guard never fires. That is the point of it. It exists for the
path where something *else* proposed the action: the Session-7 LLM classifier, a
hand-built proposal, a future taxonomy edit that gets a row wrong. This is the
containment, and it is why it keys on the failure class rather than on the
error string.

**Why not the error string.** §6.3's property test asserts on
`error_reason == "payment_risk_check_failed"`, which misses
`payment_failed`/`business` — the other row §4 routes to RISK_BLOCK, and the one
whose classification is precautionary rather than evidential. Keying on the
class covers both, and keeps covering any row added later.
"""
from __future__ import annotations

from vasool.diagnosis.taxonomy import FailureClass, InterventionType
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict


class RiskBlockGuard(Guard):
    name = "RiskBlockGuard"
    statute = "Card network norms on retrying declined authorisations"
    # VERIFY: the card networks' retry rules are referenced from Razorpay's and
    # the networks' public documentation, not from a scheme rulebook we hold.
    # The argument in taxonomy.md §2 does not depend on the citation being
    # exact — three of its four grounds stand without it — but the statute
    # column should not imply we have read the rulebook.

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.proposal.failure_class is FailureClass.RISK_BLOCK

    def check(self, ctx: GuardContext) -> Verdict:
        if ctx.proposal.is_contact:
            return self.block(
                "zero outbound on a risk decline: if the decline was a false "
                "positive, an unexpected payment message to a customer whose "
                "instrument may be compromised is structurally a phishing "
                "attack, and we would be training them to click one"
            )
        if ctx.proposal.intervention is not InterventionType.HUMAN_QUEUE:
            return self.block(
                f"{ctx.proposal.intervention.value} on a risk-declined payment: "
                "retrying a declined authorisation may breach network rules, "
                "degrades a decline ratio the merchant cannot repair, and if it "
                "was fraud it is the fraudster's tool. A human decides."
            )
        # Reached only when the taxonomy already chose HUMAN_QUEUE, which is
        # every RISK_BLOCK row on the rules path. The reason is spelled out
        # because "RiskBlockGuard ALLOW" beside a card-network citation reads
        # as the containment failing, when it is the containment having nothing
        # left to contain -- the state machine still refuses to let a handoff
        # reach the executor.
        return self.allow(
            "nothing to refuse -- the proposal is already HUMAN_QUEUE. "
            "The handoff is escalated, never executed."
        )


# ---- vasool/policy/guards/spend_cap.py ----
"""The merchant's daily blast radius.

A ceiling on the value re-presented in one day. Self-imposed — this is an
operability limit, not regulation, and it must not appear in the report card's
statute column.

**Defers where the spec blocks.** A daily ceiling expires: it resets. A recovery
killed because it happened to arrive late in the queue on a busy day is lost
revenue for no compliance gain, and there is a real instant to name. So it
defers, and logs loudly — hitting the cap is operational signal about the day,
not about the payment.

**Except when deferring could never help.** A single retry worth more than the
entire daily ceiling would breach the cap tomorrow, and the day after, forever.
That is not a condition that expires, so it blocks. This is the edge case the
defer-iff-it-expires rule exists to catch, and it is easy to miss because the
guard's usual behaviour is so obviously a deferral.

**The deferral respects the retry quiet hours.** Splitting the quiet-hours rule
between the planes left one gap: the classifier holds retries out of 00:00-06:00
IST at classify time, and nothing re-checks it afterwards, so a guard deferring
to midnight would walk an action straight back into the window. Deferring to the
first legal moment instead closes it, and reuses the classifier's arithmetic
rather than restating it.
"""
from __future__ import annotations

import logging
from datetime import datetime, timedelta

from vasool.diagnosis.rules import IST, hold_out_of_quiet_hours
from vasool.policy.facts import GuardContext
from vasool.policy.guards.base import Guard
from vasool.policy.verdict import Verdict

log = logging.getLogger(__name__)


def _next_reset(effective_at: datetime) -> datetime:
    """The first legal moment of the next IST day."""
    local = effective_at.astimezone(IST)
    midnight = (local + timedelta(days=1)).replace(
        hour=0, minute=0, second=0, microsecond=0
    )
    return hold_out_of_quiet_hours(midnight)


class SpendCapGuard(Guard):
    name = "SpendCapGuard"
    statute = None
    """Self-imposed. A merchant's own ceiling is not a clause."""

    def applies_to(self, ctx: GuardContext) -> bool:
        return ctx.proposal.is_retry

    def check(self, ctx: GuardContext) -> Verdict:
        cap = ctx.facts.merchant.daily_retry_cap_paise
        amount = ctx.proposal.amount_paise

        # This is the final policy-plane check for the taxonomy's 00:00-06:00
        # retry exclusion.  Classify-time scheduling is not enough: another
        # guard may later defer a legal retry to midnight (A18).
        legal_at = hold_out_of_quiet_hours(ctx.effective_at)
        if legal_at > ctx.effective_at:
            return self.defer(
                legal_at,
                "retry falls inside the 00:00-06:00 IST issuer-maintenance "
                "quiet period",
            )

        if amount > cap:
            return self.block(
                f"a single ₹{amount / 100:,.2f} retry exceeds the whole ₹"
                f"{cap / 100:,.2f} daily ceiling — no reset makes it fit, so "
                "deferring it would defer it forever"
            )

        if ctx.facts.spent_today_paise + amount > cap:
            log.warning(
                "merchant %s daily retry cap reached: %d + %d > %d — deferring",
                ctx.facts.merchant.merchant_id,
                ctx.facts.spent_today_paise,
                amount,
                cap,
            )
            return self.defer(
                _next_reset(ctx.effective_at),
                f"₹{ctx.facts.spent_today_paise / 100:,.2f} already re-presented "
                f"today against a ₹{cap / 100:,.2f} ceiling",
            )
        return self.allow()

